from pool import ConnectionPool

_pool = ConnectionPool(size=2)


def run_task(task_fn):
    """从池里取连接执行任务，无论成败都在 finally 中归还连接。"""
    conn = _pool.acquire()
    try:
        return task_fn(conn)
    finally:
        conn.close()

import itertools

_lock_ids = itertools.count(1)


class PooledConnection:
    def __init__(self, pool):
        self._pool = pool
        self.cid = next(_lock_ids)
        self._in_pool = False

    def close(self):
        # 归属语义：只有从池里取出的连接才能归还；已归还的再次 close 不重复归还
        if not self._in_pool:
            self._in_pool = True
            self._pool._release(self)


class ConnectionPool:
    """固定大小连接池。"""

    def __init__(self, size=2):
        self.size = size
        self._in_use = []
        self._created = size
        self._idle = []
        for _ in range(size):
            c = PooledConnection(self)
            c._in_pool = True
            self._idle.append(c)

    @property
    def in_use_count(self):
        return len(self._in_use)

    @property
    def idle_count(self):
        return len(self._idle)

    def acquire(self):
        if self._idle:
            conn = self._idle.pop()
        elif self._created < self.size + 8:
            self._created += 1
            conn = PooledConnection(self)
        else:
            raise RuntimeError('pool exhausted')
        conn._in_pool = False
        self._in_use.append(conn)
        return conn

    def _release(self, conn):
        if conn in self._in_use:
            self._in_use.remove(conn)
        self._idle.append(conn)

