import time
import functools


def timed(fn):
    """记录耗时的装饰器。必须用 functools.wraps 保留被装饰函数的元数据。"""

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        t0 = time.time()
        try:
            return fn(*args, **kwargs)
        finally:
            elapsed = time.time() - t0
            wrapper.last_elapsed = elapsed
    return wrapper
